// Convert input points to CGAL points
internal::DT dt;
for (const auto& p : points) {
    dt.insert(internal::Point_2(p.x(), p.y()));
}

// Check if the triangulation is valid
assert(dt.is_valid());

// Construct the Voronoi diagram
internal::VD vd(dt);

// Prepare the result vector
std::vector<std::vector<Point2d>> voronoiCells;

// Iterate over all faces in the Voronoi diagram
for (auto fit = vd.faces_begin(); fit != vd.faces_end(); ++fit) {
    std::vector<Point2d> cellVertices;
    internal::Ccb_halfedge_circulator ec_start = fit->ccb();
    internal::Ccb_halfedge_circulator ec = ec_start;

    // Collect all vertices of the current Voronoi cell
    do {
        if (ec->has_source()) {
            auto p = ec->source()->point();
            cellVertices.emplace_back(p.x(), p.y());
        }
    } while (++ec != ec_start);

    // Only add non-empty cells
    if (!cellVertices.empty()) {
        voronoiCells.push_back(cellVertices);
    }
}

return voronoiCells;

